// TreinON runtime configuration.
// Empty = use the values built into the app (hosted Supabase / Vercel).
// On a club's own server this file is generated at start-up, e.g.:
//   window.__TREINON_CONFIG__ = { supabaseUrl: "https://api.clube.pt", supabaseAnonKey: "eyJ..." };
window.__TREINON_CONFIG__ = window.__TREINON_CONFIG__ || {};
